var e=[{slug:`weeknight-tomato-pasta`,name:`Weeknight tomato pasta`,meta:{en:`25 min · Easy`,ua:`25 хв · Просто`},text:{en:`A quick sauce built on browned garlic, ripe tomatoes and a splash of pasta water.`,ua:`Швидкий соус із підсмаженого часнику, стиглих томатів і трохи води від пасти.`},servings:{en:`Serves 4`,ua:`На 4 порції`},ingredients:[{en:`400 g spaghetti`,ua:`400 г спагеті`},{en:`4 tablespoons olive oil`,ua:`4 столові ложки оливкової олії`},{en:`4 cloves garlic, sliced`,ua:`4 зубчики часнику, нарізані пластинками`},{en:`800 g ripe tomatoes, chopped`,ua:`800 г стиглих томатів, подрібнених`},{en:`Salt and black pepper`,ua:`Сіль і чорний перець`},{en:`A handful of basil`,ua:`Жменя базиліка`}],steps:[{en:`Boil the pasta in well-salted water until just tender. Keep a cup of the water.`,ua:`Зваріть пасту в добре посоленій воді до легкої м’якості. Збережіть склянку води.`},{en:`Warm the oil and cook the garlic until pale gold, then add the tomatoes.`,ua:`Розігрійте олію, підсмажте часник до блідо-золотого кольору й додайте томати.`},{en:`Simmer for ten minutes, until the sauce thickens. Season to taste.`,ua:`Тушкуйте десять хвилин, поки соус загусне. Посоліть і поперчіть за смаком.`},{en:`Toss the pasta in the sauce with a splash of pasta water and finish with basil.`,ua:`Змішайте пасту із соусом і трохи води від пасти, додайте базилік.`}],tip:{en:`Starchy pasta water helps the sauce cling to the pasta.`,ua:`Крохмалиста вода від пасти допомагає соусу обволікати макарони.`}},{slug:`crisp-roast-chicken`,name:`Crisp roast chicken`,meta:{en:`1 h 15 min · Medium`,ua:`1 год 15 хв · Середньо`},text:{en:`Dry the skin, salt early and let the oven do the rest for a golden crust.`,ua:`Підсушіть шкірку, посоліть заздалегідь і дозвольте духовці зробити решту для золотистої скоринки.`},servings:{en:`Serves 4`,ua:`На 4 порції`},ingredients:[{en:`1 whole chicken, about 1.6 kg`,ua:`1 ціла курка, близько 1,6 кг`},{en:`1 tablespoon salt`,ua:`1 столова ложка солі`},{en:`2 tablespoons butter, softened`,ua:`2 столові ложки м’якого вершкового масла`},{en:`1 lemon`,ua:`1 лимон`},{en:`A few sprigs of thyme`,ua:`Кілька гілочок чебрецю`}],steps:[{en:`Pat the chicken dry and rub the salt over the skin. Rest it uncovered in the fridge for a few hours.`,ua:`Промокніть курку й натріть шкірку сіллю. Залиште її відкритою в холодильнику на кілька годин.`},{en:`Heat the oven to 220 °C. Rub the butter under and over the skin and fill the cavity with lemon and thyme.`,ua:`Розігрійте духовку до 220 °C. Розподіліть масло під шкіркою й на ній, а в порожнину покладіть лимон і чебрець.`},{en:`Roast for about 50 minutes, until the skin is deep gold.`,ua:`Запікайте близько 50 хвилин, поки шкірка стане глибоко золотистою.`},{en:`Check that the thickest part of the thigh reaches 74 °C, then rest for 15 minutes before carving.`,ua:`Переконайтеся, що найтовща частина стегна прогрілася до 74 °C, і дайте курці відпочити 15 хвилин перед нарізанням.`}],tip:{en:`Use a thermometer: colour alone does not show that the chicken is safe to eat.`,ua:`Користуйтеся термометром: колір сам по собі не доводить, що курка безпечна.`}},{slug:`no-knead-bread`,name:`No-knead bread`,meta:{en:`18 h · Easy`,ua:`18 год · Просто`},text:{en:`Almost no work, a long rest and a loaf with an open crumb.`,ua:`Майже без зусиль, зі спокійним вистоюванням і буханкою з повітряним м’якушем.`},servings:{en:`Makes 1 loaf`,ua:`1 буханка`},ingredients:[{en:`500 g bread flour`,ua:`500 г хлібного борошна`},{en:`375 g water`,ua:`375 г води`},{en:`10 g salt`,ua:`10 г солі`},{en:`2 g instant yeast`,ua:`2 г швидкодіючих дріжджів`}],steps:[{en:`Stir everything together until there is no dry flour. The dough will be sticky.`,ua:`Змішайте всі інгредієнти, щоб не лишилося сухого борошна. Тісто буде липким.`},{en:`Cover and leave at room temperature for 12 to 18 hours, until bubbly and doubled.`,ua:`Накрийте й залиште за кімнатної температури на 12–18 годин, поки тісто стане пухирчастим і збільшиться вдвічі.`},{en:`Fold the dough on a floured surface, shape it into a round and rest it for one hour.`,ua:`Складіть тісто на присипаній борошном поверхні, сформуйте кулю й залиште на годину.`},{en:`Bake in a preheated lidded pot at 230 °C for 30 minutes covered and 15 minutes uncovered.`,ua:`Випікайте в розігрітому горщику з кришкою за 230 °C: 30 хвилин під кришкою та 15 без неї.`}],tip:{en:`Let the loaf cool for an hour before slicing, so the crumb can set.`,ua:`Дайте буханці охолонути годину перед нарізанням, щоб м’якуш стабілізувався.`}}];export{e as t};